INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_carbonate_bicarbonate_acid_test', 'forensics', 'forensics_qualitative_analysis_solids', 'Carbonate and bicarbonate acid reaction test', 'Add dilute acid to carbonate or bicarbonate solids and recognize immediate effervescence of CO2 to distinguish them from non-carbonate solids.', ARRAY['CO2 bubbles', 'NaHCO3', 'Na2CO3', 'CaCO3', 'HCl test', 'effervescence']::text[], 5) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_iodine_starch_test', 'forensics', 'forensics_qualitative_analysis_solids', 'Iodine test for starch', 'Use iodine solution to detect cornstarch by the blue-black starch-iodine complex and distinguish starch from glucose and sucrose.', ARRAY['I2-KI', 'blue-black complex', 'amylose helix', 'cornstarch positive']::text[], 6) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_benedicts_test_reducing_sugars', 'forensics', 'forensics_qualitative_analysis_solids', 'Benedict''s test for reducing sugars', 'Heat sample with Benedict''s reagent and interpret brick-red Cu2O precipitate as positive for reducing sugars such as glucose.', ARRAY['Cu2O', 'brick-red ppt', 'glucose positive', 'sucrose negative', 'reducing ends']::text[], 7) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_sucrose_glucose_differentiation', 'forensics', 'forensics_qualitative_analysis_solids', 'Distinguishing sucrose from glucose', 'Perform Benedict''s test before and after acid hydrolysis to identify sucrose, negative before and positive after, versus glucose, positive before.', ARRAY['sucrose nonreducing', 'acid hydrolysis', 'Benedict''s before/after', 'glucose reducing']::text[], 8) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_ammonium_ion_test', 'forensics', 'forensics_qualitative_analysis_solids', 'Ammonium ion test with sodium hydroxide', 'Warm sample with NaOH and detect ammonia gas by odor or red litmus turning blue as a positive test for NH4Cl.', ARRAY['NH4Cl', 'NH3 gas', 'red litmus blue', 'NaOH']::text[], 9) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_acetate_ion_test', 'forensics', 'forensics_qualitative_analysis_solids', 'Acetate detection by acid odor', 'Add dilute sulfuric acid to sodium acetate and recognize vinegar-like acetic acid odor as a positive acetate test.', ARRAY['CH3COOH odor', 'NaC2H3O2', 'acidification', 'vinegar smell']::text[], 10) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_nitrate_test_brown_ring', 'forensics', 'forensics_qualitative_analysis_solids', 'Nitrate test by brown ring', 'Layer iron(II) sulfate with concentrated sulfuric acid on sample solution and observe a brown ring at the interface as positive nitrate.', ARRAY['FeSO4', 'concentrated H2SO4', 'Fe(NO)2+ brown ring', 'NO3- detection', 'interface']::text[], 11) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_boric_acid_identification', 'forensics', 'forensics_qualitative_analysis_solids', 'Boric acid identification', 'Identify boric acid by its green flame color, weak acid behavior, and greater solubility in hot water than in cold water.', ARRAY['H3BO3', 'green flame', 'weak acid', 'hot water soluble', 'borate']::text[], 12) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_physical_appearance_of_known_solids', 'forensics', 'forensics_qualitative_analysis_solids', 'Physical appearance and crystalline form of listed solids', 'Use crystal size, powder texture, color, and hygroscopic or deliquescent behavior as preliminary distinguishing observations among the 15 listed solids.', ARRAY['crystalline vs powder', 'white solids', 'LiCl hygroscopic', 'texture', 'visual observation']::text[], 13) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
