INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_polymer_density_separation', 'forensics', 'forensics_polymers_fibers_hair', 'Polymer density separation by flotation', 'Use water, saturated salt, alcohol, and oil to separate common plastics by density ranges and identify PETE, HDPE, PS, LDPE, PP, PVC, PMMA, and PC.', ARRAY['density g/mL', 'sink/float', 'water <1 g/mL', 'PP floats', 'PVC sinks', 'PMMA vs PC']::text[], 0) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_polymer_flame_test', 'forensics', 'forensics_polymers_fibers_hair', 'Polymer flame test observations', 'Ignite small polymer samples and interpret flame color, smoke, dripping, self-extinguishing behavior, and odor to distinguish plastics.', ARRAY['green flame PVC', 'black soot PS', 'paraffin odor PP/PE', 'acrid HCl PVC', 'dripping', 'self-extinguish']::text[], 1) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_polymer_resin_code_physical_properties', 'forensics', 'forensics_polymers_fibers_hair', 'Resin codes and physical properties of plastics', 'Correlate SPI resin codes 1-7 with polymer names and use clarity, flexibility, and hardness to distinguish PETE, HDPE, PVC, LDPE, PP, PS, and PC.', ARRAY['SPI codes', 'PETE #1', 'HDPE #2', 'PVC #3', 'LDPE #4', 'PP #5']::text[], 2) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_polymer_chemical_tests', 'forensics', 'forensics_polymers_fibers_hair', 'Chemical spot tests for polymers', 'Use specific chemical tests such as copper wire flame, acetone solubility, and alcohol flame to identify PVC, PMMA, PS, and other plastics.', ARRAY['Beilstein copper wire', 'acetone dissolves PMMA', 'chlorine green flame', 'chemical resistance', 'spot test']::text[], 3) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_natural_fiber_microscopy', 'forensics', 'forensics_polymers_fibers_hair', 'Microscopic identification of natural fibers', 'Use microscope morphology including flat twists in cotton, nodes in linen, scales on wool, and smooth transparent tubes in silk to identify natural fibers.', ARRAY['cotton twist', 'linen bamboo nodes', 'wool scales', 'silk smooth', 'fiber microscopy']::text[], 4) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_synthetic_fiber_burn_test', 'forensics', 'forensics_polymers_fibers_hair', 'Synthetic fiber burn and melt identification', 'Ignite fibers and use melting, bead formation, ash, odor, and smoke to distinguish nylon, polyester, and spandex.', ARRAY['nylon blue base', 'polyester sweet odor', 'spandex black sticky ash', 'melt vs burn', 'bead']::text[], 5) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_human_vs_animal_hair_medulla', 'forensics', 'forensics_polymers_fibers_hair', 'Medulla patterns and human vs animal hair', 'Compare medullary index, pattern type, and pigment distribution to distinguish human hair from animal hair.', ARRAY['medullary index >1/2 animal', 'continuous medulla', 'interrupted', 'fragmented', 'human <1/3']::text[], 6) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_hair_cuticle_scale_patterns', 'forensics', 'forensics_polymers_fibers_hair', 'Cuticle scale patterns in hair', 'Recognize coronal, spinous, and imbricate cuticle scale patterns from casts or microscopy for species identification.', ARRAY['coronal', 'spinous', 'imbricate', 'scale cast', 'human hair imbricate']::text[], 7) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_hair_root_and_growth_phase', 'forensics', 'forensics_polymers_fibers_hair', 'Hair root morphology and growth phase', 'Distinguish anagen, catagen, and telogen root appearance and use tissue tags or follicle shape to infer forcible removal or natural shedding.', ARRAY['anagen club', 'telogen bulb', 'tissue tag', 'forcible removal', 'growth phase']::text[], 8) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_species_identification_from_hair', 'forensics', 'forensics_polymers_fibers_hair', 'Species identification from hair samples', 'Combine medulla type, cuticle scale pattern, color banding, and diameter to identify human, bat, cow, squirrel, and horse hair.', ARRAY['bat coronal scales', 'cow medulla continuous', 'horse diameter', 'squirrel banded', 'species key']::text[], 9) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
