INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_paper_chromatography_principle', 'forensics', 'forensics_chromatography_mass_spectrometry', 'Paper chromatography separation principle', 'Explain how analytes partition between a polar stationary phase and a mobile solvent and predict migration based on polarity and intermolecular forces.', ARRAY['stationary phase', 'mobile phase', 'partition', 'polarity', 'capillary action']::text[], 0) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_tlc_principle', 'forensics', 'forensics_chromatography_mass_spectrometry', 'Thin-layer chromatography principle', 'Describe TLC separation on silica or alumina plates, compare with paper, and use UV visualization or staining to locate analyte spots.', ARRAY['silica gel', 'alumina', 'adsorption', 'UV visualization', 'spotting']::text[], 1) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_rf_calculation', 'forensics', 'forensics_chromatography_mass_spectrometry', 'Rf calculation and interpretation', 'Calculate retention factor as distance moved by compound divided by distance moved by solvent front and use Rf to compare unknowns with standards.', ARRAY['Rf = d_compound/d_solvent', '0<Rf<1', 'identification', 'standard comparison']::text[], 2) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_chromatography_development_technique', 'forensics', 'forensics_chromatography_mass_spectrometry', 'Chromatogram development and sample application', 'Prepare a chromatogram by spotting small concentrated samples, suspending the plate or paper without submerging the spot, and developing in a sealed chamber.', ARRAY['spotting', 'sealed chamber', 'solvent level', 'tailing', 'wicking']::text[], 3) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_chromatography_visualization_methods', 'forensics', 'forensics_chromatography_mass_spectrometry', 'Visualization of chromatograms', 'Choose appropriate visualization methods such as UV lamp, iodine vapor, ninhydrin, or visible dyes to reveal separated colorless analytes.', ARRAY['UV', 'I2 vapor', 'ninhydrin', 'visible dye', 'spot visualization']::text[], 4) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_mass_spectrum_molecular_ion', 'forensics', 'forensics_chromatography_mass_spectrometry', 'Molecular ion and molar mass from mass spectra', 'Identify the molecular ion peak to determine molar mass and distinguish M+ from fragment peaks and recognize M+1 and M+2 isotopic peaks.', ARRAY['M+ peak', 'm/z highest', 'isotopic peaks', 'molar mass', 'M+1 carbon-13']::text[], 5) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_mass_spectrum_fragmentation', 'forensics', 'forensics_chromatography_mass_spectrometry', 'Fragmentation patterns in mass spectra', 'Interpret major fragment peaks as losses of stable groups and use base peak and relative abundance to recognize structural subunits.', ARRAY['base peak', 'relative abundance', 'fragment losses', 'm/z', 'cation radicals']::text[], 6) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_isotope_patterns_ms', 'forensics', 'forensics_chromatography_mass_spectrometry', 'Isotope patterns for chlorine and bromine', 'Recognize characteristic M:M+2 intensity ratios for compounds containing chlorine about 3:1 or bromine about 1:1 from mass spectra.', ARRAY['Cl 35/37', 'Br 79/81', 'M+2', '3:1', '1:1']::text[], 7) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_chromatography_vs_mass_spectrometry', 'forensics', 'forensics_chromatography_mass_spectrometry', 'Comparing chromatograms and mass spectra', 'Distinguish retention-based separation output from mass-to-charge spectral output and use both to identify forensic samples.', ARRAY['retention time', 'm/z spectrum', 'hyphenated GC-MS', 'qualitative identification']::text[], 8) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_topics (id, event_id, name, sort_order) VALUES ('forensics_fingerprints', 'forensics', 'Fingerprint patterns, development, and terminology', 4) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, name = EXCLUDED.name, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_fingerprint_ridge_skin_structure', 'forensics', 'forensics_fingerprints', 'Friction ridge skin anatomy', 'Explain how friction ridges form from dermal papillae into the epidermis and how sweat and oil secretions create latent prints.', ARRAY['dermal papillae', 'epidermis', 'sweat pores', 'latent residue', 'friction ridges']::text[], 0) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_fingerprint_pattern_classes_arch', 'forensics', 'forensics_fingerprints', 'Arch fingerprint patterns', 'Identify and distinguish plain arches and tented arches by ridge flow across the finger and central spike or loop features.', ARRAY['plain arch', 'tented arch', 'no delta', 'central spike']::text[], 1) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_fingerprint_pattern_loops', 'forensics', 'forensics_fingerprints', 'Loop fingerprint patterns', 'Classify ulnar and radial loops by delta, core, and loop opening direction relative to the hand bones.', ARRAY['ulnar loop', 'radial loop', 'one delta', 'core', 'loop direction']::text[], 2) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_fingerprint_pattern_whorls', 'forensics', 'forensics_fingerprints', 'Whorl fingerprint patterns', 'Distinguish plain whorl, central pocket loop, double loop, and accidental whorl using number and placement of deltas and ridge structure.', ARRAY['plain whorl', 'central pocket loop', 'double loop', 'accidental', 'two deltas']::text[], 3) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_fingerprint_minutiae', 'forensics', 'forensics_fingerprints', 'Fingerprint minutiae identification', 'Recognize ending ridges, bifurcations, dots, lakes, spurs, and crossovers in a print and use their positions for individualization.', ARRAY['ending ridge', 'bifurcation', 'dot', 'lake', 'spur', 'crossover']::text[], 4) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_fingerprint_development_powder', 'forensics', 'forensics_fingerprints', 'Powder development of latent prints', 'Apply fine fingerprint powder with a brush to nonporous surfaces and lift using tape and backing cards to develop and preserve latent prints.', ARRAY['black/gray powder', 'magnetic powder', 'nonporous', 'lifting tape', 'preservation']::text[], 5) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_fingerprint_development_chemical', 'forensics', 'forensics_fingerprints', 'Chemical development of latent prints', 'Choose and explain chemical methods including iodine fuming, ninhydrin, silver nitrate, and cyanoacrylate for porous and nonporous surfaces.', ARRAY['iodine fuming', 'ninhydrin', 'silver nitrate', 'cyanoacrylate', 'porous vs nonporous']::text[], 6) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_fingerprint_cyanoacrylate_fuming', 'forensics', 'forensics_fingerprints', 'Cyanoacrylate fuming for latent prints', 'Describe superglue fuming chamber reactions with moisture and amino acids to form white polymerized ridges on nonporous evidence and use fluorescent dye staining for enhancement.', ARRAY['superglue', 'white polymer', 'humidity', 'RUVIS', 'dye stain']::text[], 7) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_latent_patent_plastic_prints', 'forensics', 'forensics_fingerprints', 'Types of fingerprints: latent, patent, plastic', 'Classify prints as latent, patent, or plastic and predict the optimal development method for each surface and print type.', ARRAY['latent', 'patent', 'plastic', '3D impression', 'development method']::text[], 8) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
