INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_dna_str_analysis', 'forensics', 'forensics_dna_blood_evidence', 'STR DNA profiling', 'Explain how short tandem repeat loci are counted by repeat number and how allele peaks on electropherograms identify a DNA profile.', ARRAY['STR', 'CODIS', 'allele', 'repeat number', 'loci']::text[], 0) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_dna_electropherogram_interpretation', 'forensics', 'forensics_dna_blood_evidence', 'DNA electropherogram peak interpretation', 'Read dye-labeled allele peaks, distinguish stutter and pull-up artifacts, and match allele sizes using size-standard ladders.', ARRAY['relative fluorescence units', 'allelic ladder', 'stutter', 'pull-up', 'size standard']::text[], 1) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_pcr_amplification', 'forensics', 'forensics_dna_blood_evidence', 'PCR amplification of DNA', 'Explain denaturation, annealing, and extension temperature cycling and how exponential amplification copies target STR regions from trace DNA.', ARRAY['denaturation 94-98C', 'annealing', 'Taq polymerase', 'extension 72C', 'exponential amplification']::text[], 2) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_dna_extraction_quantification', 'forensics', 'forensics_dna_blood_evidence', 'DNA extraction and quantification', 'Lyse cells, purify DNA from proteins and inhibitors, and quantify DNA yield or concentration using UV absorbance or fluorometry before amplification.', ARRAY['cell lysis', 'silica membrane', 'A260/280', 'DNA quantification', 'inhibitor removal']::text[], 3) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_blood_typing_abo', 'forensics', 'forensics_dna_blood_evidence', 'ABO blood typing with antisera', 'Add anti-A, anti-B, and anti-D antisera to blood and interpret agglutination patterns to determine ABO and Rh type.', ARRAY['anti-A', 'anti-B', 'anti-D', 'agglutination', 'blood group']::text[], 4) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_blood_cell_microscopy', 'forensics', 'forensics_dna_blood_evidence', 'Blood cell microscopy and species identification', 'Use microscope slides to distinguish human blood cells from avian, mammalian, and reptile or amphibian blood by RBC shape, nucleation, and size.', ARRAY['enucleated RBC human', 'nucleated avian', 'elliptical amphibian', 'mammalian', 'species blood']::text[], 5) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_presumptive_confirmatory_blood', 'forensics', 'forensics_dna_blood_evidence', 'Presumptive vs confirmatory blood tests', 'Choose Kastle-Meyer, luminol, or leucomalachite green as presumptive and Takayama or immunological tests as confirmatory and interpret controls.', ARRAY['Kastle-Meyer', 'luminol', 'leucomalachite green', 'confirmatory', 'false positives']::text[], 6) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_dna_chromatogram_vs_electropherogram', 'forensics', 'forensics_dna_blood_evidence', 'DNA sequencing chromatogram reading', 'Read Sanger sequence chromatograms by colored dye peaks and quality scores and distinguish heterozygous peaks from background noise.', ARRAY['Sanger', 'dye-terminator', 'heterozygous double peak', 'quality score', 'base calling']::text[], 7) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_dna_mixture_interpretation', 'forensics', 'forensics_dna_blood_evidence', 'DNA mixture and contamination interpretation', 'Recognize mixed DNA profiles with more than two alleles at loci, interpret major and minor contributors, and identify possible contamination or allelic dropout.', ARRAY['mixed profile', 'major/minor', 'dropout', 'allelic peaks', 'contamination']::text[], 8) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
