INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_glass_refractive_index', 'forensics', 'forensics_glass_spatter_ballistics', 'Glass refractive index by immersion', 'Use the Becke line method with immersion oils of known refractive index to determine glass refractive index and compare questioned and known glass.', ARRAY['Becke line', 'immersion oil', 'nD', 'match point', 'glass comparison']::text[], 0) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
