INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_glass_radial_concentric_fractures', 'forensics', 'forensics_glass_spatter_ballistics', 'Radial and concentric glass fractures', 'Distinguish radial cracks from concentric circles and use their orientation and morphology to identify impact side and direction.', ARRAY['radial cracks', 'concentric cracks', 'impact side', 'crater', 'tension/recompression']::text[], 2) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_glass_fracture_sequence', 'forensics', 'forensics_glass_spatter_ballistics', 'Determining glass fracture order', 'Apply fracture termination rules where cracks stop at existing fractures to sequence multiple bullet or impact hits in glass.', ARRAY['termination', 'fracture sequence', 'existing crack stop', 'bullet holes', 'multi-hit']::text[], 3) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_bloodstain_angle_of_impact', 'forensics', 'forensics_glass_spatter_ballistics', 'Bloodstain angle of impact calculation', 'Measure stain width and length and calculate angle of impact using sin θ = width/length to reconstruct drop direction.', ARRAY['sin θ = width/length', 'impact angle', 'circular 90°', 'elliptical', 'spatter trigonometry']::text[], 4) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
