INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_bullet_lands_grooves', 'forensics', 'forensics_glass_spatter_ballistics', 'Bullet lands and grooves striations', 'Explain rifling marks on bullets including lands and grooves and compare individual striations on test-fired bullets under a comparison microscope.', ARRAY['rifling', 'lands', 'grooves', 'comparison microscope', 'individual striations']::text[], 7) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
