INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_blow_fly_life_cycle_pmi', 'forensics', 'forensics_entomology_palynology_soil_tracks', 'Blow fly life cycle and PMI', 'Estimate postmortem interval using developmental stages of blow fly eggs, larval instars, prepupae, pupae, and adults at known temperatures.', ARRAY['egg', '1st instar', '2nd instar', '3rd instar', 'pupation', 'PMI']::text[], 0) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
