INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_soil_chemical_mineral_tests', 'forensics', 'forensics_entomology_palynology_soil_tracks', 'Soil chemical and mineral tests', 'Test soil pH, effervescence with acid, and presence of minerals such as quartz using simple chemical or optical tests to link soil samples.', ARRAY['pH', 'HCl effervescence', 'mineral grains', 'quartz', 'soil comparison']::text[], 5) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
