INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_lab_controls_standards', 'forensics', 'forensics_lab_methods_data', 'Use of controls, blanks, and standards', 'Include positive and negative controls, reagent blanks, and known standards in every test to validate results and detect contamination.', ARRAY['positive control', 'negative control', 'reagent blank', 'standard', 'validation']::text[], 0) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_measurement_precision_significant_figures', 'forensics', 'forensics_lab_methods_data', 'Measurement precision and significant figures', 'Record measurements with correct precision and significant figures and use balances, graduated cylinders, rulers, and micropipettes to match instrument uncertainty.', ARRAY['significant figures', 'uncertainty', 'precision', 'meniscus', 'micropipette']::text[], 1) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
