INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_sample_preparation', 'forensics', 'forensics_lab_methods_data', 'Sample preparation for forensic tests', 'Prepare solid or liquid samples by cutting, scraping, dissolving, filtering, centrifuging, or diluting without altering evidence and preserve representative portions.', ARRAY['scraping', 'dissolving', 'filtration', 'centrifugation', 'preservation']::text[], 3) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_lab_safety_ppe', 'forensics', 'forensics_lab_methods_data', 'Laboratory safety and personal protection', 'Apply PPE, fume hood use, chemical hygiene, eye and skin wash, and safe handling and disposal of biological and chemical evidence in forensic labs.', ARRAY['gloves', 'goggles', 'fume hood', 'biohazard', 'disposal']::text[], 4) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_documentation_chain_of_custody', 'forensics', 'forensics_lab_methods_data', 'Documentation and chain of custody', 'Maintain labeled evidence seals, log transfer dates and signatures, and record observations with initials and dates to preserve admissibility and continuity.', ARRAY['chain of custody', 'evidence seal', 'labeling', 'documentation', 'admissibility']::text[], 5) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_data_recording_calculation', 'forensics', 'forensics_lab_methods_data', 'Data recording and result calculations', 'Organize qualitative observations and quantitative measurements into tables and calculate concentrations, dilutions, densities, and angle measurements with correct units.', ARRAY['data table', 'unit conversion', 'concentration', 'dilution', 'calculation']::text[], 6) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_instrument_calibration', 'forensics', 'forensics_lab_methods_data', 'Instrument calibration and verification', 'Calibrate balances, pH meters, thermocyclers, and micropipettes using known standards and verify calibration before and after evidence measurements.', ARRAY['calibration', 'verification', 'balance check', 'pH meter calibration', 'pipette accuracy']::text[], 7) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_avoiding_cross_contamination', 'forensics', 'forensics_lab_methods_data', 'Avoiding cross-contamination', 'Use sterile or disposable tools, change gloves between items, separate evidence samples, and clean surfaces to prevent evidence contamination and false associations.', ARRAY['cross-contamination', 'sterile tools', 'glove change', 'evidence separation', 'clean bench']::text[], 8) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_error_and_uncertainty', 'forensics', 'forensics_lab_methods_data', 'Error sources and uncertainty in forensic measurements', 'Identify random and systematic errors, estimate uncertainty, and evaluate false positives and negatives in qualitative and quantitative forensic tests.', ARRAY['random error', 'systematic error', 'uncertainty', 'false positive', 'false negative']::text[], 9) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_topics (id, event_id, name, sort_order) VALUES ('forensics_crime_scene_reasoning', 'forensics', 'Crime scene analysis and suspect reasoning', 9) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, name = EXCLUDED.name, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_class_vs_individual_evidence', 'forensics', 'forensics_crime_scene_reasoning', 'Class vs individual evidence', 'Distinguish class characteristics such as fiber type or blood group from individualizing characteristics such as fingerprint minutiae, DNA profiles, or bullet striations and assess probative value.', ARRAY['class evidence', 'individual evidence', 'probative value', 'identification', 'exclusion']::text[], 0) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_inculpatory_exculpatory', 'forensics', 'forensics_crime_scene_reasoning', 'Inculpatory vs exculpatory evidence', 'Classify evidence as inculpatory, supporting involvement, or exculpatory, tending to exclude a suspect, and use both to test hypotheses.', ARRAY['inculpatory', 'exculpatory', 'hypothesis', 'inclusion', 'exclusion']::text[], 1) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_suspect_implication_elimination', 'forensics', 'forensics_crime_scene_reasoning', 'Suspect implication and elimination logic', 'Write reasoning that compares suspect reference samples to evidence, stating matches, mismatches, and whether evidence implicates or eliminates each suspect.', ARRAY['match', 'mismatch', 'eliminate', 'implicate', 'reference sample']::text[], 2) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_integrating_multiple_evidence', 'forensics', 'forensics_crime_scene_reasoning', 'Integrating multiple evidence types', 'Combine results from different evidence categories such as DNA, fiber, and fingerprints into a coherent scenario and evaluate corroboration and contradictions.', ARRAY['corroboration', 'contradiction', 'multiple lines', 'scenario', 'weight of evidence']::text[], 3) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_evidence_admissibility_chain_defects', 'forensics', 'forensics_crime_scene_reasoning', 'Evaluating evidence admissibility and chain of custody defects', 'Assess whether breaks in chain of custody, mislabeling, or improper storage compromise evidence integrity and affect admissibility in suspect reasoning.', ARRAY['break in custody', 'mislabeling', 'admissibility', 'evidence integrity', 'court challenge']::text[], 4) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_reliability_limitations', 'forensics', 'forensics_crime_scene_reasoning', 'Reliability and limitations of forensic tests', 'Assess sensitivity, specificity, false positive and negative rates, and interpretation limits for each forensic test before drawing suspect conclusions.', ARRAY['sensitivity', 'specificity', 'false positive', 'false negative', 'limitations']::text[], 5) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_scenario_reconstruction', 'forensics', 'forensics_crime_scene_reasoning', 'Scenario reconstruction and hypothesis testing', 'Use evidence patterns such as spatter, glass, and tracks to reconstruct the sequence of events and test alternative hypotheses for consistency.', ARRAY['sequence of events', 'alternative hypotheses', 'consistency', 'reconstruction', 'crime scene']::text[], 6) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('forensics_written_conclusion_structure', 'forensics', 'forensics_crime_scene_reasoning', 'Writing forensic conclusion reasoning', 'Construct clear evidence-based conclusions using claim-evidence-reasoning format with specific test results and logical justification for each suspect.', ARRAY['claim', 'evidence', 'reasoning', 'conclusion', 'written response']::text[], 7) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
