INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('thermodynamics_system_classification', 'thermodynamics', 'thermodynamics_systems_properties_temperature', 'Classify thermodynamic systems', 'Identify whether a system is open, closed, or isolated by whether mass and energy cross its boundary.', ARRAY['open system', 'closed system', 'isolated system', 'boundary', 'surroundings']::text[], 0) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
INSERT INTO public.taxonomy_concepts (id, event_id, topic_id, name, description, depth_tags, sort_order) VALUES ('thermodynamics_state_vs_path_functions', 'thermodynamics', 'thermodynamics_systems_properties_temperature', 'Distinguish state and path functions', 'Classify properties such as internal energy, enthalpy, temperature, work, and heat as state functions or path functions based on path dependence.', ARRAY['state function', 'path function', 'internal energy', 'work', 'heat']::text[], 1) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, topic_id = EXCLUDED.topic_id, name = EXCLUDED.name, description = EXCLUDED.description, depth_tags = EXCLUDED.depth_tags, sort_order = EXCLUDED.sort_order;
