FROM public.taxonomy_concepts
WHERE event_id IN ('circuit_lab', 'designer_genes', 'forensics', 'thermodynamics', 'rocks_minerals', 'astronomy', 'protein_modeling', 'botany', 'remote_sensing', 'disease_detectives', 'dynamic_planet')
